package com.elitedarkkaiser.nubialy;
import android.graphics.*;
import android.view.View;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import com.google.android.material.button.MaterialButton;
import com.google.android.material.materialswitch.MaterialSwitch;
import com.google.android.material.slider.Slider;
import com.elitedarkkaiser.nubialy.SurfaceStyle.QsTheme;
import java.util.*;
import java.util.function.*;
/** Focused pages share the established hex/RGB picker and one parent draft/save worker. */
final class QsThemeEditor {
 private final AppCompatActivity a;private final Supplier<QsTheme> read;private final Consumer<QsTheme> save;private final Runnable pick;
 private Bitmap previewImage;private String previewHash="";
 void image(Bitmap bitmap,String hash){previewImage=bitmap;previewHash=hash;refresh();}
 private final List<View> previews=new ArrayList<>();private final List<Runnable> labels=new ArrayList<>();
 QsThemeEditor(AppCompatActivity a,Supplier<QsTheme> read,Consumer<QsTheme> save,Runnable pick){this.a=a;this.read=read;this.save=save;this.pick=pick;}
 private int dp(float v){return PersonalizationUi.dp(a,v);}
 private TextView text(String value,int size){TextView v=new TextView(a);v.setText(value);v.setTextSize(size);v.setTextColor(a.getColor(R.color.on_surface));v.setPadding(0,dp(10),0,dp(8));return v;}
 private MaterialButton button(LinearLayout p,String label){MaterialButton b=new MaterialButton(a);b.setText(label);b.setCornerRadius(dp(28));p.addView(b,new LinearLayout.LayoutParams(-1,-2));return b;}
 private void change(int key,int value){save.accept(read.get().with(key,value));refresh();}
 void refresh(){for(Runnable r:labels)r.run();for(View v:previews)v.invalidate();}
 private void preview(LinearLayout parent){View view=new View(a){final Paint p=new Paint(3);@Override protected void onDraw(Canvas c){super.onDraw(c);QsTheme t=read.get();float w=getWidth(),h=getHeight();p.setShader(null);p.setColor(t.header()!=0?t.headerColor():0xff303036);c.drawRoundRect(0,0,w,h,dp(24),dp(24),p);if(t.header()!=0&&previewImage!=null&&t.image().equals(previewHash)){int save=c.save();c.clipRect(0,0,w,h);float scale=Math.max(w/previewImage.getWidth(),h/previewImage.getHeight());float bw=previewImage.getWidth()*scale,bh=previewImage.getHeight()*scale;p.setAlpha(t.opacity()*255/100);c.drawBitmap(previewImage,null,new RectF((w-bw)/2,(h-bh)/2,(w+bw)/2,(h+bh)/2),p);p.setColor(Color.BLACK);p.setAlpha(t.dim()*t.opacity()*255/10000);c.drawRect(0,0,w,h,p);p.setAlpha(255);c.restoreToCount(save);}float x=dp(18),y=dp(26),tw=(w-dp(54))/2,th=dp(64);p.setColor(t.activeBackground()!=0?t.activeBackground():a.getColor(R.color.primary));if(t.twoTone()!=0)p.setShader(new LinearGradient(x,y,x+tw,y+th,t.accent(),t.secondAccent(),Shader.TileMode.CLAMP));c.drawRoundRect(x,y,x+tw,y+th,dp(20),dp(20),p);p.setShader(null);p.setColor(t.inactiveBackground()!=0?t.inactiveBackground():0xff48474f);c.drawRoundRect(x+tw+dp(18),y,w-x,y+th,dp(20),dp(20),p);p.setTextSize(dp(16));p.setColor(t.activeIcon()!=0?t.activeIcon():0xff202028);c.drawText("Wi-Fi",x+dp(15),y+dp(38),p);p.setColor(t.inactiveIcon()!=0?t.inactiveIcon():0xffeeeeee);c.drawText("Bluetooth",x+tw+dp(30),y+dp(38),p);p.setTextSize(dp(13));p.setColor(t.primaryLabel()!=0?t.primaryLabel():0xffeeeeee);c.drawText("Main label",x,h-dp(34),p);p.setColor(t.secondaryLabel()!=0?t.secondaryLabel():0xffbab8c5);c.drawText("Secondary label",x,h-dp(14),p);}};previews.add(view);parent.addView(view,new LinearLayout.LayoutParams(-1,dp(158)));parent.addView(text("Draft preview · press Apply on this page to apply",13));}
 private int get(int key){QsTheme t=read.get();return switch(key){case 0->t.activeBackground();case 1->t.inactiveBackground();case 2->t.activeIcon();case 3->t.inactiveIcon();case 4->t.primaryLabel();case 5->t.secondaryLabel();case 7->t.accent();case 8->t.secondAccent();case 10->t.headerColor();case 15->t.clockColor();case 16->t.dateColor();case 17->t.statusColor();default->throw new IllegalArgumentException();};}
 private void color(LinearLayout p,String title,int key,boolean nativeOption){
  LinearLayout row=new LinearLayout(a);row.setGravity(android.view.Gravity.CENTER_VERTICAL);row.setMinimumHeight(dp(52));p.addView(row,new LinearLayout.LayoutParams(-1,-2));
  TextView name=text(title,14);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));
  MaterialButton b=new MaterialButton(a);b.setCornerRadius(dp(14));b.setAllCaps(false);b.setTag("qs-color:"+key);b.setMinWidth(dp(88));b.setInsetTop(dp(4));b.setInsetBottom(dp(4));b.setStrokeWidth(dp(1));b.setStrokeColor(android.content.res.ColorStateList.valueOf(a.getColor(R.color.surface_container_high)));b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.TRANSPARENT));b.setTextColor(a.getColor(R.color.primary));row.addView(b,new LinearLayout.LayoutParams(-2,dp(44)));labels.add(()->{b.setText(get(key)==0?"Native":ClockColorPolicy.hex(get(key)));b.setContentDescription("Choose "+title+", "+b.getText());});b.setOnClickListener(v->ColorPickerDialog.show(a,title,"Quick Settings",get(key)==0?a.getColor(R.color.primary):get(key),value->change(key,value)));
  if(nativeOption){MaterialButton reset=new MaterialButton(a);reset.setText("↺");reset.setTextSize(20);reset.setMinWidth(0);reset.setMinimumWidth(0);reset.setPadding(0,0,0,0);reset.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.TRANSPARENT));reset.setTextColor(a.getColor(R.color.on_surface_variant));reset.setContentDescription("Use native "+title);reset.setOnClickListener(v->change(key,0));row.addView(reset,new LinearLayout.LayoutParams(dp(48),dp(48)));}
 }

 private void toggle(LinearLayout p,String title,int key,boolean checked){MaterialSwitch v=new MaterialSwitch(a);v.setText(title);v.setChecked(checked);p.addView(v);v.setOnCheckedChangeListener((b,value)->change(key,value?1:0));}
 private void slider(LinearLayout p,String title,int key,int value,int min,int max){TextView label=text(title+": "+value+"%",16);p.addView(label);Slider slider=new Slider(a);slider.setValueFrom(min);slider.setValueTo(max);slider.setStepSize(1);slider.setValue(value);slider.setTag("qs-theme-slider:"+key);p.addView(slider);slider.addOnChangeListener((s,n,user)->{if(user){label.setText(title+": "+(int)n+"%");change(key,(int)n);}});}
 void header(LinearLayout p){
  p.addView(text("QS clock & date",20));color(p,"Clock color",15,true);slider(p,"Clock size",18,read.get().clockScale(),70,130);color(p,"Date color",16,true);slider(p,"Date size",19,read.get().dateScale(),70,130);
  p.addView(text("QS status icons",20));color(p,"Status icon color",17,true);slider(p,"Status icon size",20,read.get().statusScale(),70,130);p.addView(text("Applies only inside the QS header. Visibility stays managed by System UI. Large sizes may clip inside native bounds.",14));refresh();
 }
 void colors(LinearLayout p){String[] names={"Active tile background","Inactive tile background","Active icons","Inactive icons","Main labels","Secondary labels"};for(int i=0;i<6;i++)color(p,names[i],i,true);p.addView(text("Unavailable tiles keep their native state colors. Tile actions and labels remain stock.",14));twoTone(p);refresh();}
 void twoTone(LinearLayout p){p.addView(text("Two-Tone",20));toggle(p,"Enable Two-Tone active tiles",6,read.get().twoTone()!=0);color(p,"First accent",7,false);color(p,"Second accent",8,false);p.addView(text("Active tiles blend these accents. Your selected tile style adds its shading and rim over the gradient. Inactive tiles follow native or your chosen colors.",14));refresh();}
 void background(LinearLayout p){toggle(p,"Enable upper QS background",9,read.get().header()!=0);color(p,"Background color",10,false);TextView current=text("",14);p.addView(current);labels.add(()->current.setText(read.get().image().isEmpty()?"Solid background selected":"Custom image selected · center crop"));button(p,"Choose background image").setOnClickListener(v->pick.run());button(p,"Use solid background").setOnClickListener(v->{save.accept(read.get().withImage(""));refresh();});slider(p,"Background opacity",12,read.get().opacity(),0,100);slider(p,"Dark overlay",13,read.get().dim(),0,100);slider(p,"Upper area height",14,read.get().height(),10,80);p.addView(text("Images are center-cropped into the upper QS area. Controls and notifications remain interactive. Enable this page after importing. Expansion and landscape need device testing.",14));refresh();}
}
